/* ============================================================================
 * discloseField() privacy-leak tests (Wave 2 N1, adversarial).
 *
 * Stealable mechanisms (~/workspace/midnight-wave2/WINNERS-6MO.md):
 *  - DarkStake blinding-reuse regression: the test FAILS if a disclosure
 *    blinding (here: the disclosureSeed) ever repeats across fills, and a
 *    deliberately-reused blinding MUST be linkable-detectable.
 *  - TacitPay U-17 four-encoding absence: hex/decimal/LE/base64 encodings of
 *    the field must not appear in any disclose output.
 *
 * Real circuit (CONTRACT/src/remit_quote.compact, CONTRACT-1 final):
 *  discloseField(fieldSelector: Uint<8>, auditorKey: Bytes<32>,
 *                sealedBox: Bytes<160>): []
 *  - witnesses: disclosureSeed + the six fill fields (side, baseAmount,
 *    quoteAmount, principal, counterparty, mandateId)
 *  - recomputes salts = fieldSalt(seed, i) and commitments under the pool's
 *    exact scheme; discloses auditRoot, c_selector, selector, auditorKey,
 *    sealedBox, nullifier = Hash("remit:dnull" || commitment || auditorKey)
 *  - ledger-write boundary: disclosureNullifiers.insert(nullifier)
 *    (kills replayed disclosure AND fixes proof:false)
 *  - HONEST HYBRID: the field is sealed OFF-CIRCUIT with RMTB1
 *    (X25519 ECDH + XChaCha20-Poly1305, packages/core/src/box.ts);
 *    plaintext = value32 || salt32 (64 bytes). The circuit makes NO claim
 *    about box contents — auditor-detected, not circuit-prevented.
 *
 * Non-claims respected (§5 HONEST-LIMITS.md): field freshness is NOT claimed
 * (a stale fill's field discloses as cleanly as a live one's); auditorKey is
 * a key, not an identity.
 *
 * World-visible channels in the simulator (compact-runtime erases disclose()):
 *  public circuit inputs (selector, auditorKey, sealedBox) + ledger state +
 *  the disclosed values (root, commitment, nullifier), which the test
 *  recomputes with the same stdlib primitives as an oracle (repo precedent:
 *  pureCircuits.claimTag in quote-sim.test.ts). privateTranscriptOutputs is
 *  NEVER included — it carries witness secrets.
 * ========================================================================== */

const CPK = "11".repeat(32);
const BOX_RAW_LEN = 141; // "RMTB1"(5) || ephPub(32) || nonce(24) || ct(80)
const BOX_LEN = 160; // zero-padded by the driver, per circuit header
const U8 = new CompactTypeUnsignedInteger(255n, 1);
const U64 = new CompactTypeUnsignedInteger((1n << 64n) - 1n, 8);
const B32 = new CompactTypeBytes(32);

/** One fill's disclosable audit vector + its disclosure blinding (the seed). */
type Fill = {
  side: bigint;
  baseAmount: bigint;
  quoteAmount: bigint;
  principal: Uint8Array;
  counterparty: Uint8Array;
  mandateId: Uint8Array;
  /** The blinding: salts and commitments derive from this. Fresh per fill. */
  seed: Uint8Array;
};

/** DarkStake core: the blinding source. The suite FAILS if it ever repeats. */
const usedSeeds = new Set<string>();
function freshSeed(): Uint8Array {
  const s = randomBytes32();
  const h = toHex(s);
  expect(usedSeeds.has(h), "disclosure seed reused: blinding source regressed (DarkStake)").toBe(false);
  usedSeeds.add(h);
  return s;
}

/** Assert distinct fills never share a blinding — the test FAILS on reuse. */
function assertNoSeedReuseAcrossFills(fills: Fill[]): void {
  const seen = new Set<string>();
  for (const f of fills) {
    const h = toHex(f.seed);
    expect(seen.has(h), `disclosure seed reused across fills — disclosures linkable: ${h}`).toBe(false);
    seen.add(h);
  }
}

function randomUint64(): bigint {
  return bytesToBigint(randomBytes32().subarray(0, 8), false);
}

function bytesToBigint(b: Uint8Array, littleEndian: boolean): bigint {
  const bytes = littleEndian ? [...b].reverse() : [...b];
  let n = 0n;
  for (const x of bytes) n = (n << 8n) | BigInt(x);
  return n;
}

function makeFill(): Fill {
  return {
    side: BigInt(Math.floor(Math.random() * 2)),
    baseAmount: randomUint64(),
    quoteAmount: randomUint64(),
    principal: randomBytes32(),
    counterparty: randomBytes32(),
    mandateId: randomBytes32(),
    seed: freshSeed(),
  };
}

/** value32: field as big-endian 32 bytes (Uint right-aligned, Bytes<32> as-is). */
function value32(idx: number, fill: Fill): Uint8Array {
  const out = new Uint8Array(32);
  if (idx === 0) {
    out[31] = Number(fill.side);
  } else if (idx === 1 || idx === 2) {
    const v = idx === 1 ? fill.baseAmount : fill.quoteAmount;
    for (let i = 0; i < 8; i++) out[31 - i] = Number((v >> BigInt(8 * i)) & 0xffn);
  } else {
    out.set(idx === 3 ? fill.principal : idx === 4 ? fill.counterparty : fill.mandateId);
  }
  return out;
}

/** salt32: fieldSalt(seed, idx) — the pool's exact scheme (inlined in-circuit). */
function salt32(fill: Fill, idx: number): Uint8Array {
  return poolPureCircuits.fieldSalt(fill.seed, BigInt(idx));
}

/** Oracle for the disclosed commitment c_idx = persistentCommit(value, salt). */
function commitmentOf(idx: number, fill: Fill): Uint8Array {
  const salt = salt32(fill, idx);
  if (idx === 0) return persistentCommit(U8, fill.side, salt);
  if (idx === 1) return persistentCommit(U64, fill.baseAmount, salt);
  if (idx === 2) return persistentCommit(U64, fill.quoteAmount, salt);
  const v = idx === 3 ? fill.principal : idx === 4 ? fill.counterparty : fill.mandateId;
  return persistentCommit(B32, v, salt);
}

/** Oracle for the disclosed auditRoot = auditRootOf(c0..c5). */
function rootOf(fill: Fill): Uint8Array {
  const cs = [0, 1, 2, 3, 4, 5].map((i) => commitmentOf(i, fill));
  return poolPureCircuits.auditRootOf(cs);
}

/** Seal value32 || salt32 to the auditor with RMTB1; zero-pad to Bytes<160>. */
function sealField(fill: Fill, idx: number, auditorPubHex: string): Uint8Array {
  const pt = new Uint8Array(64);
  pt.set(value32(idx, fill), 0);
  pt.set(salt32(fill, idx), 32);
  const raw = fromBase64Url(sealTo(auditorPubHex, pt));
  expect(raw.length, "RMTB1 box must be 141 bytes for 64-byte plaintext").toBe(BOX_RAW_LEN);
  expect(Buffer.from(raw.subarray(0, 5)).toString(), "RMTB1 magic").toBe("RMTB1");
  const padded = new Uint8Array(BOX_LEN);
  padded.set(raw);
  return padded;
}

// ---- local witnesses (self-contained: do not depend on the in-flight
// CONTRACT-2 witness file; names match CONTRACT-1's final circuit) ----

type DisclosePS = {
  version: 1;
  callerSk?: number[];
  dSeed?: number[];
  dSide?: string;
  dBase?: string;
  dQuote?: string;
  dPrincipal?: number[];
  dCounterparty?: number[];
  dMandateId?: number[];
};

function reqBytes(v: number[] | undefined, name: string): Uint8Array {
  if (!v) throw new Error(`WITNESS_MISSING: quote disclose value not staged: ${name}`);
  return Uint8Array.from(v);
}
function reqUint(v: string | undefined, name: string): bigint {
  if (v === undefined) throw new Error(`WITNESS_MISSING: quote disclose value not staged: ${name}`);
  return BigInt(v);
}

const discloseWitnesses: Witnesses<DisclosePS> = {
  callerSecret: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => {
    if (!privateState?.callerSk) throw new Error("WITNESS_MISSING: quote caller secret not staged");
    return [privateState, Uint8Array.from(privateState.callerSk)];
  },
  disclosureSeed: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqBytes(privateState?.dSeed, "dSeed"),
  ],
  disclosureSide: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqUint(privateState?.dSide, "dSide"),
  ],
  disclosureBaseAmount: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqUint(privateState?.dBase, "dBase"),
  ],
  disclosureQuoteAmount: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqUint(privateState?.dQuote, "dQuote"),
  ],
  disclosurePrincipal: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqBytes(privateState?.dPrincipal, "dPrincipal"),
  ],
  disclosureCounterparty: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqBytes(privateState?.dCounterparty, "dCounterparty"),
  ],
  disclosureMandateId: ({ privateState }: WitnessContext<Ledger, DisclosePS>) => [
    privateState,
    reqBytes(privateState?.dMandateId, "dMandateId"),
  ],
};

type QuoteSim = {
  contract: Contract<DisclosePS, typeof discloseWitnesses>;
  ctx: CircuitContext<DisclosePS>;
  ps: DisclosePS;
};

function bootQuote(): QuoteSim {
  const contract = new Contract(discloseWitnesses);
  const ps: DisclosePS = { version: 1, callerSk: Array.from(randomBytes32()) };
  const built = contract.initialState(createConstructorContext(ps, CPK));
  const ctx = createCircuitContext<DisclosePS>(
    dummyContractAddress(),
    CPK,
    built.currentContractState,
    built.currentPrivateState,
  );
  return { contract, ctx, ps: built.currentPrivateState as DisclosePS };
}

function nullifiersOf(ctx: CircuitContext<DisclosePS>): Uint8Array[] {
  const ld = ledger(ctx.currentQueryContext.state) as Ledger;
  return Array.from(ld.disclosureNullifiers as unknown as Iterable<Uint8Array>);
}

function dumpLedger(ctx: CircuitContext<DisclosePS>): string {
  const ld = ledger(ctx.currentQueryContext.state) as unknown as Record<string, unknown>;
  const parts: string[] = [];
  const walk = (v: unknown): string => {
    if (v instanceof Uint8Array) return toHex(v);
    if (typeof v === "bigint") return v.toString(10);
    if (typeof v === "function") return "<fn>";
    if (v && typeof v === "object") {
      const rec = v as Record<string, unknown>;
      const maybeIterable = rec as unknown as { [Symbol.iterator]?: unknown };
      if (typeof maybeIterable[Symbol.iterator] === "function") {
        return `[${Array.from(rec as unknown as Iterable<unknown>).map(walk).join(",")}]`;
      }
      return `{${Object.entries(rec).map(([k, x]) => `${k}:${walk(x)}`).join(",")}}`;
    }
    return String(v);
  };
  for (const [k, v] of Object.entries(ld)) parts.push(`${k}=${walk(v)}`);
  return parts.join("\n");
}

function clearStaged(ps: DisclosePS): DisclosePS {
  const { dSeed: _a, dSide: _b, dBase: _c, dQuote: _d, dPrincipal: _e, dCounterparty: _f, dMandateId: _g, ...rest } = ps;
  void _a; void _b; void _c; void _d; void _e; void _f; void _g;
  return rest as DisclosePS;
}

/** Every disclose output produced in this file — the 4-encoding sweep target. */
type Auditor = { publicHex: string; secretHex: string };
type DisclosureRecord = {
  idx: number;
  selector: bigint;
  auditorPubHex: string;
  auditorSecretHex: string;
  fill: Fill;
  box: Uint8Array;
  nullifier: Uint8Array;
  commitment: Uint8Array;
  root: Uint8Array;
  salt: Uint8Array;
  seed: Uint8Array;
  value32: Uint8Array;
  haystack: string;
};
const allDisclosures: DisclosureRecord[] = [];

function runDisclose(
  q: QuoteSim,
  fill: Fill,
  selector: bigint,
  auditor: Auditor,
): { q: QuoteSim; rec: DisclosureRecord; res: CircuitResults<DisclosePS, []> } {
  const idx = Number(selector);
  const box = sealField(fill, idx, auditor.publicHex);
  const auditorKey = fromHex(auditor.publicHex);
  const before = new Set(nullifiersOf(q.ctx).map(toHex));
  const staged: DisclosePS = {
    ...q.ps,
    dSeed: Array.from(fill.seed),
    dSide: fill.side.toString(),
    dBase: fill.baseAmount.toString(),
    dQuote: fill.quoteAmount.toString(),
    dPrincipal: Array.from(fill.principal),
    dCounterparty: Array.from(fill.counterparty),
    dMandateId: Array.from(fill.mandateId),
  };
  const ctx: CircuitContext<DisclosePS> = { ...q.ctx, currentPrivateState: staged };
  const res = q.contract.impureCircuits.discloseField(ctx, selector, auditorKey, box);
  const next: CircuitContext<DisclosePS> = res.context;
  const fresh = nullifiersOf(next).filter((n) => !before.has(toHex(n)));
  expect(fresh.length, "discloseField must write exactly one disclosure nullifier").toBe(1);
  // The 19-byte zero pad is a fixed public constant (circuit header documents
  // zero-padding to Bytes<160>): it carries no information. It is asserted
  // constant here and EXCLUDED from the encoding-absence scans, where
  // zero-run encodings would otherwise match it trivially (false positive).
  expect(
    toHex(box.subarray(BOX_RAW_LEN)),
    "sealedBox padding must be the public zero constant",
  ).toBe("00".repeat(BOX_LEN - BOX_RAW_LEN));

  // World-visible outputs (per the circuit's audit table: root, commitment,
  // selector, auditorKey, sealedBox, nullifier are disclosed to the world).
  // The scanned box bytes are the 141 information-bearing bytes only.
  const commitment = commitmentOf(idx, fill);
  const root = rootOf(fill);
  const haystack = [
    `selector:${selector.toString(10)}`,
    `auditorKey:${toHex(auditorKey)}`,
    `sealedBox:${toHex(box.subarray(0, BOX_RAW_LEN))}`,
    `commitment:${toHex(commitment)}`,
    `auditRoot:${toHex(root)}`,
    `nullifier:${toHex(fresh[0])}`,
    `ledger:${dumpLedger(next)}`,
  ].join("\n");
  const rec: DisclosureRecord = {
    idx,
    selector,
    auditorPubHex: auditor.publicHex,
    auditorSecretHex: auditor.secretHex,
    fill,
    box,
    nullifier: fresh[0],
    commitment,
    root,
    salt: salt32(fill, idx),
    seed: fill.seed,
    value32: value32(idx, fill),
    haystack,
  };
  allDisclosures.push(rec);
  const nq: QuoteSim = { ...q, ctx: next, ps: clearStaged(next.currentPrivateState as DisclosePS) };
  return { q: nq, rec, res };
}

/**
 * Auditor-level linkage detector (DarkStake pattern, public-outputs-plus-
 * auditor-key): decrypt both sealed boxes with the auditor secret key and
 * compare the sealed salts. Identical salt32 across disclosures of DIFFERENT
 * fills ==> the disclosure seed (blinding) was reused ==> linkable.
 */
function sealedSalt(box160: Uint8Array, auditorSecretHex: string): Uint8Array {
  const pt = openSealed(auditorSecretHex, toBase64Url(box160.subarray(0, BOX_RAW_LEN)));
  expect(pt.length, "sealed plaintext must be value32||salt32").toBe(64);
  return pt.subarray(32, 64);
}
function detectSeedReuse(a: DisclosureRecord, b: DisclosureRecord, auditorSecretHex: string): boolean {
  return bytesEq(sealedSalt(a.box, auditorSecretHex), sealedSalt(b.box, auditorSecretHex));
}

/** The six field values as secrets for absence scans (bigint + bytes forms). */
function fieldSecrets(fill: Fill): Array<Uint8Array | bigint> {
  return [fill.side, fill.baseAmount, fill.quoteAmount, fill.principal, fill.counterparty, fill.mandateId];
}

describe("discloseField() privacy leaks (Wave 2 N1, adversarial)", () => {
  describe("1. blinding-reuse linkage (DarkStake regression pattern)", () => {
    it("fresh blinding per fill; reuse is linkable-detectable; the suite fails on reuse", () => {
      const auditor = rfqKeyPair();
      let q = bootQuote();

      // Honest: two different fills, fresh blindings.
      const f1 = makeFill();
      const f2 = makeFill();
      assertNoSeedReuseAcrossFills([f1, f2]); // FAILS if the blinding source repeats
      const d1 = runDisclose(q, f1, 1n, auditor);
      q = d1.q;
      const d2 = runDisclose(q, f2, 1n, auditor);
      q = d2.q;

      // Unlinkable: distinct sealed salts, distinct commitments/nullifiers.
      expect(detectSeedReuse(d1.rec, d2.rec, auditor.secretHex)).toBe(false);
      expect(toHex(d1.rec.commitment)).not.toBe(toHex(d2.rec.commitment));
      expect(toHex(d1.rec.nullifier)).not.toBe(toHex(d2.rec.nullifier));
      // The sealed salt matches the oracle (auditor recompute story holds).
      expect(toHex(sealedSalt(d1.rec.box, auditor.secretHex))).toBe(toHex(salt32(f1, 1)));

      // ACCEPT+document: same fill to two auditors re-discloses the SAME
      // commitment (same committed values — linkable by design, not a leak).
      const auditor2 = rfqKeyPair();
      const d1b = runDisclose(q, f1, 1n, auditor2);
      q = d1b.q;
      expect(toHex(d1b.rec.commitment)).toBe(toHex(d1.rec.commitment));
      expect(toHex(d1b.rec.nullifier)).not.toBe(toHex(d1.rec.nullifier));

      // Adversarial: the SAME blinding reused for a different fill.
      const f3 = makeFill();
      f3.seed = f1.seed; // deliberate reuse — the DarkStake regression
      const d3 = runDisclose(q, f3, 1n, auditor);
      q = d3.q;
      // MUST be linkable-detectable: identical sealed salt across fills.
      expect(detectSeedReuse(d1.rec, d3.rec, auditor.secretHex)).toBe(true);
      // ...and the honesty gate FAILS on the reused pair:
      expect(() => assertNoSeedReuseAcrossFills([f1, f3])).toThrow(/seed reused/);
    });
  });

  describe("2. four-encoding absence (TacitPay U-17 pattern)", () => {
    it("no hex/decimal/LE/base64 encoding of any field appears in any disclose output", () => {
      expect(allDisclosures.length, "expected disclosures from earlier tests").toBeGreaterThan(0);
      for (const rec of allDisclosures) {
        const label = `discloseField-4enc(selector=${rec.selector})`;
        const hay = rec.haystack;
        // The disclosed field, both endian interpretations (value32 is BE).
        // The four encodings, named explicitly for diagnostics.
        for (const [tag, n] of [["BE", bytesToBigint(rec.value32, false)], ["LE", bytesToBigint(rec.value32, true)]] as const) {
          const [hex, , dec, leHex, leB64] = encodingsOfBigint(n);
          for (const [ename, e] of [["hex", hex], ["decimal", dec], ["LE", leHex], ["base64", leB64]] as const) {
            if (e.length < 8) continue;
            expect(
              hay.toLowerCase().includes(e.toLowerCase()),
              `privacy leak (${label}): ${tag} field ${ename} encoding present: ${e}`,
            ).toBe(false);
          }
        }
        // Full-spectrum backstop: every staged field value, the sealed salt,
        // and the seed must be absent from world-visible outputs.
        assertAbsent(hay, fieldSecrets(rec.fill), `${label}/fields`);
        assertAbsent(hay, [rec.salt], `${label}/sealed-salt`);
        assertAbsent(hay, [rec.seed], `${label}/seed`);
      }
    });

    it("sealed salt stays sealed and ciphertext differs from plaintext (N3 regression)", () => {
      expect(allDisclosures.length).toBeGreaterThan(0);
      for (const rec of allDisclosures) {
        const label = `discloseField-box(selector=${rec.selector})`;
        // Ciphertext != plaintext: raw box bytes differ from value32||salt32,
        // and no plaintext encoding appears in the world-visible outputs.
        const pt = new Uint8Array(64);
        pt.set(rec.value32, 0);
        pt.set(rec.salt, 32);
        expect(toHex(rec.box.subarray(0, BOX_RAW_LEN))).not.toBe(toHex(pt));
        for (const e of encodingsOfBytes(pt)) {
          if (e.length < 8) continue;
          expect(
            rec.haystack.toLowerCase().includes(e.toLowerCase()),
            `privacy leak (${label}): plaintext encoding present: ${e.slice(0, 32)}...`,
          ).toBe(false);
        }
        // Auditor-only readability: the auditor's key opens the box and
        // recovers exactly value32||salt32; any other key fails.
        const opened = openSealed(rec.auditorSecretHex, toBase64Url(rec.box.subarray(0, BOX_RAW_LEN)));
        expect(Buffer.from(opened).equals(Buffer.from(pt)), `${label}: auditor must recover value32||salt32`).toBe(true);
        expect(() =>
          openSealed(rfqKeyPair().secretHex, toBase64Url(rec.box.subarray(0, BOX_RAW_LEN))),
        ).toThrow(/unseal failed/);
      }
    });
  });

  describe("3. disclosure-nullifier uniqueness", () => {
    it("nullifiers unique across (field, auditorKey); replay of a pair is rejected", () => {
      const a1 = rfqKeyPair();
      const a2 = rfqKeyPair();
      let q = bootQuote();
      const f1 = makeFill();
      const f2 = makeFill();

      const n1 = runDisclose(q, f1, 1n, a1);
      q = n1.q;
      const n2 = runDisclose(q, f1, 2n, a2); // same fill, other field+auditor
      q = n2.q;
      const n3 = runDisclose(q, f2, 1n, a1); // other fill, same auditor
      q = n3.q;

      const seen = [n1.rec.nullifier, n2.rec.nullifier, n3.rec.nullifier].map(toHex);
      expect(new Set(seen).size, "disclosure nullifiers must be unique across (field, auditorKey)").toBe(3);
      // (f1,a1) vs (f1,a2): auditorKey is bound into the nullifier.
      expect(seen[0]).not.toBe(seen[1]);
      // (f1,a1) vs (f2,a1): the field commitment is bound into the nullifier.
      expect(seen[0]).not.toBe(seen[2]);

      // Replay: the exact (field, auditorKey) pair reproduces the nullifier
      // and the circuit rejects it — the ledger-write boundary.
      expect(() => runDisclose(q, f1, 1n, a1)).toThrow(/disclosure already recorded/);
    });
  });

  describe("4. fieldSelector metadata-leak audit", () => {
    it("selector is a value-independent position index (< 6); smuggling a value is rejected", () => {
      const auditor = rfqKeyPair();
      let q = bootQuote();

      // Value-independence: same position, different values -> same selector.
      const fa = makeFill();
      const fb = makeFill();
      const da = runDisclose(q, fa, 1n, auditor);
      q = da.q;
      const db = runDisclose(q, fb, 1n, auditor);
      q = db.q;
      expect(da.rec.selector).toBe(1n);
      expect(db.rec.selector).toBe(1n);
      expect(fa.baseAmount).not.toBe(fb.baseAmount);

      // Position-encoding: all six positions disclose distinctly.
      let qq = bootQuote();
      const f = makeFill();
      const sels = new Set<bigint>();
      for (let i = 0n; i < 6n; i++) {
        const d = runDisclose(qq, f, i, auditor);
        qq = d.q;
        sels.add(d.rec.selector);
      }
      expect(sels).toEqual(new Set([0n, 1n, 2n, 3n, 4n, 5n]));

      // Adversarial: a selector smuggling a value is rejected in-circuit.
      const q2 = bootQuote();
      const fz = makeFill();
      expect(() => runDisclose(q2, fz, 6n, auditor)).toThrow(/bad field selector/);
      expect(() => runDisclose(q2, fz, 255n, auditor)).toThrow(/bad field selector/);

      // Metadata audit over every disclose output: enum-sized, and no
      // >=8-char field encoding collides with the selector's forms.
      expect(allDisclosures.length).toBeGreaterThan(0);
      for (const rec of allDisclosures) {
        expect(rec.selector < 6n, `fieldSelector ${rec.selector} is not enum-sized`).toBe(true);
        const selForms = new Set([rec.selector.toString(10), rec.selector.toString(16)]);
        const be = bytesToBigint(rec.value32, false);
        const le = bytesToBigint(rec.value32, true);
        for (const n of [be, le]) {
          for (const e of encodingsOfBigint(n)) {
            if (e.length < 8) continue;
            expect(selForms.has(e.toLowerCase()), `fieldSelector collides with field encoding ${e}`).toBe(false);
          }
        }
      }
    });
  });
});
